const base = '/home/user/deepseek-harness/.claude/worktrees/agent-a1e049d2aeb1b7a69/data/proving-ground'
const skip = new Set(['folds', 'datasets', 'tools', 'loop'])
for (const name of readdirSync(base).sort()) {
  const dir = join(base, name)
  if (skip.has(name) || !existsSync(join(dir, 'trajectories.jsonl'))) continue
  const lines = readFileSync(join(dir, 'trajectories.jsonl'), 'utf8').split('\n').filter(Boolean)
  const formats = new Set()
  let withTerms = 0
  let heldOut = 0
  for (const l of lines) {
    const t = JSON.parse(l)
    formats.add(t.format)
    if (t.terms !== undefined) withTerms += 1
