  const heldOut = []
  for (const { sessionId, path } of logs) {
    const { meta, events } = scanLog(readFileSync(path))
    const trajectory = foldTrajectory(meta, events)
    if (trajectory.environment?.heldOut === true) {
      heldOut.push(sessionId)
